    return wrapped

def async_wrapper(func):
    @functools.wraps(func)
    async def wrapped(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapped

cases = [
    ("sync_func", sync_func, False),
    ("async_func", async_func, True),
    ("wrapped_sync", wrapper(sync_func), False),
    ("wrapped_async", wrapper(async_func), True),
    ("async_wrapped_sync", async_wrapper(sync_func), True),
    ("async_wrapped_async", async_wrapper(async_func), True),
