def is_coroutine_callable_fixed(call):
    for c in get_unwrapped_chain(call):
        if inspect.isroutine(c):
            if iscoroutinefunction(c):
                return True
        elif inspect.isclass(c):
            continue
        else:
            dunder_call = getattr(c, "__call__", None)
            if dunder_call and iscoroutinefunction(dunder_call):
                return True
    return False

